<?php declare(strict_types=1);$memberRates=\Kulturhus\Verein\ContributionRates::all($db,\Kulturhus\Verein\Permissions::actor($db,(string)$_SESSION['actor'])['club_id']);$singleRate=\Kulturhus\Verein\ContributionRates::label($memberRates['single']['amount_cents']);$familyRate=\Kulturhus\Verein\ContributionRates::label($memberRates['family']['amount_cents']);$votingId=input($_GET,'application',input($_POST,'id')); ?>
<div class="page-heading"><h1>Aufnahmen entscheiden</h1><a href="?view=portal&amp;tab=application">Antragsverwaltung</a></div><div class="content">
<section class="card"><p>Die Abstimmung erfolgt durch die eingetragenen Vorstandsmitglieder. Außerhalb einer Sitzung wird ein Beschluss hier nur bei übereinstimmender Zustimmung aller Beteiligten festgestellt. Unterschiedliche Stimmen erfordern eine Beratung.</p><p>Die Stimmabgabe ist persönlich und wird mit Zeitpunkt und Erklärung gespeichert. Die Begründungen bleiben intern.</p></section>
<?php if($votingId===''):foreach($admissionVotes->applications() as $item):$answers=json_decode($item['answers'],true,512,JSON_THROW_ON_ERROR); ?><section class="card"><a href="<?= e(url(['view'=>'portal','tab'=>'admissions','application'=>$item['id']])) ?>"><?= e($answers['first_name'].' '.$answers['last_name']) ?></a></section><?php endforeach;else:$round=$admissionVotes->detail($votingId);$answers=json_decode($round['application']['answers'],true,512,JSON_THROW_ON_ERROR);$myVote=null;foreach($round['votes'] as $vote)if($vote['actor_id']===$_SESSION['actor'])$myVote=$vote; ?>
<section class="card"><?php if(!$round['id']): ?><p>Der Antrag ist eingegangen. Die Online-Abstimmung wird nach Bestätigung der Vorstandsbesetzung eröffnet.</p><?php endif ?><h2><?= e($answers['first_name'].' '.$answers['last_name']) ?></h2><dl class="data-list"><?php foreach(\Kulturhus\Verein\MembershipApplications::FIELDS as $key=>$label):if(empty($answers[$key]))continue; ?><dt><?= e($label) ?></dt><dd><?= nl2br(e($answers[$key])) ?></dd><?php endforeach ?><dt>Beitrag</dt><dd><?= e(\Kulturhus\Verein\ContributionRates::applicationLabel($answers)) ?></dd></dl><p><?= e(['pending'=>'Stimmen fehlen','discussion'=>'Unterschiedliche Stimmen · Beratung erforderlich','accepted'=>'Einstimmig für Aufnahme','rejected'=>'Einstimmig für Ablehnung'][$round['result']]) ?></p>
<p><?php foreach($admissionVotes->documents($votingId) as $document): ?><a class="btn btn-outline theme-secondary button secondary" href="<?= e(url(['admission_file'=>$document['id'],'application'=>$votingId])) ?>"><?= e($document['title']) ?> herunterladen</a> <?php endforeach ?></p><ul><?php foreach($round['people'] as $person):$cast=null;foreach($round['votes'] as $vote)if($vote['actor_id']===$person['actor_id'])$cast=$vote; ?><li><?= e($person['name'].' · '.$person['office']) ?>: <?= $cast?($cast['choice']==='yes'?'Ja zur Aufnahme':'Ja zum Ablehnungsbeschluss'):'Noch offen' ?><?php if($cast): ?> · <?= e($cast['voted_at']) ?><?php if($cast['reason']!==''): ?><p><?= nl2br(e($cast['reason'])) ?></p><?php endif;endif ?></li><?php endforeach ?></ul></section>
<?php if($round['id']&&!$myVote&&$round['application']['status']==='pending'&&$admissionVotes->canVote()): ?><form method="post" class="card"><?= csrf().hidden('action','admission-vote').hidden('id',$votingId) ?><h2>Meine Entscheidung</h2><label>Entscheidung<select class="form-control" name="choice" required><option value="">Bitte auswählen</option><option value="yes">Ja · ich stimme dem Aufnahmebeschluss zu</option><option value="no">Nein · ich stimme dem Ablehnungsbeschluss zu</option></select></label><label>Begründung (bei Nein erforderlich)<textarea class="form-control" name="reason" maxlength="2000" rows="4"></textarea></label><label class="check"><input class="check" type="checkbox" name="confirmed" value="1" required>Ich gebe diese Erklärung persönlich als stimmberechtigtes Vorstandsmitglied ab und bin bei diesem Antrag nicht vom Stimmrecht ausgeschlossen.</label><button class="btn btn-solid theme-primary">Stimme verbindlich abgeben</button></form><?php elseif($myVote): ?><p>Deine Stimme ist protokolliert.</p><?php endif;endif ?></div>
